@@ -0,0 +1,62 @@
+#!/usr/bin/env node
+// Optional pre-delivery diagnostic. Usage:
+//   node check_model.js <final_model.js> <inputs.txt> [topk]
+// inputs.txt: one predict() input string per line (every catalogue entry, plus training entries).
+// Hard failures (exit 1): non-finite output, non-deterministic output, call-order dependence, constant output.
+// Resolution figures are reported for judgement only; they are not a pass/fail gate.
+const fs = require('fs');
+const path = require('path');
+const [modelPath, inputsPath, topkArg] = process.argv.slice(2);
+if (!modelPath || !inputsPath) {
+  console.error('usage: node check_model.js <final_model.js> <inputs.txt> [topk]');
+  process.exit(2);
+}
+const topk = parseInt(topkArg || '20', 10);
+const mod = require(path.resolve(modelPath));
+const predict = mod.predict || (mod.default && mod.default.predict) || mod;
+const lines = fs.readFileSync(inputsPath, 'utf8').split('\n').map(s => s.trim()).filter(Boolean);
+const uniq = Array.from(new Set(lines));
+let fail = 0;
+const bad = (m) => { console.log('FAIL: ' + m); fail = 1; };
+
+const run = (arr) => arr.map(s => predict(s));
+const a = run(uniq);
+const b = run(uniq);
+const nonFinite = a.filter(v => typeof v !== 'number' || !Number.isFinite(v)).length;
+if (nonFinite) bad(`${nonFinite} non-finite outputs`);
+if (a.some((v, i) => v !== b[i])) bad('outputs differ between two identical runs');
+
+// fixed-seed LCG shuffle so this tool needs no randomness source
+let seed = 12345;
+const rnd = () => (seed = (seed * 1664525 + 1013904223) % 4294967296) / 4294967296;
+const idx = uniq.map((_, i) => i);
+for (let i = idx.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [idx[i], idx[j]] = [idx[j], idx[i]]; }
+const c = run(idx.map(i => uniq[i]));
+if (idx.some((orig, k) => c[k] !== a[orig])) bad('outputs depend on call order');
+
+const distinct = new Set(a).size;
+console.log(`inputs=${a.length} distinct_scores=${distinct} (${(100 * distinct / a.length).toFixed(1)}%)`);
+if (distinct <= 1) bad('constant predictions');
+
+// tie blocks, with their rank position (rank 1 = highest score)
+const order = a.map((v, i) => [v, i]).sort((x, y) => y[0] - x[0]);
+const blocks = [];
+for (let r = 0; r < order.length;) {
+  let e = r;
+  while (e + 1 < order.length && order[e + 1][0] === order[r][0]) e++;
+  if (e > r) blocks.push({ score: order[r][0], size: e - r + 1, firstRank: r + 1, lastRank: e + 1 });
+  r = e + 1;
+}
+blocks.sort((x, y) => y.size - x.size);
+if (blocks.length) {
+  console.log('largest tie blocks (size, ranks, score):');
+  blocks.slice(0, 3).forEach(t => console.log(`  ${t.size} tied at ranks ${t.firstRank}-${t.lastRank} (${(100 * t.firstRank / a.length).toFixed(0)}%-${(100 * t.lastRank / a.length).toFixed(0)}% down the list), score ${t.score}`));
+} else {
+  console.log('no tied scores');
+}
+const topTies = blocks.filter(t => t.firstRank <= topk);
+if (topTies.length) console.log(`NOTE: ${topTies.length} tie block(s) touch the top ${topk}; evaluation order would decide their relative rank.`);
+console.log(`top-${topk}:`);
+order.slice(0, topk).forEach(([v, i]) => console.log(`  ${v.toPrecision(5)}  ${uniq[i]}`));
+console.log(fail ? 'RESULT: FAIL' : 'RESULT: OK (resolution figures above are for judgement)');
+process.exit(fail);
